void parseVariant(TextParser& parser, Wire::DataNode& wire)
{
    if (parser.acceptWord("Undefined"_s)) {
        wire.kind = 0;
        return;
    }
    if (parser.acceptWord("Null"_s)) {
        wire.kind = 1;
        return;
    }
    if (parser.acceptWord("Hole"_s)) {
        wire.kind = 2;
        return;
    }
    if (parser.acceptWord("Boolean"_s)) {
        wire.kind = 3;
        parser.parseRecord([&] {
            if (parser.acceptField("value"_s))
                wire.words[0] = static_cast<uint32_t>(parser.parseBool());
        });
        return;
    }
    if (parser.acceptWord("Number"_s)) {
        wire.kind = 4;
        parser.parseRecord([&] {
            if (parser.acceptField("value"_s)) {
                uint64_t bits = std::bit_cast<uint64_t>(parser.parseDouble());
                wire.words[0] = static_cast<uint32_t>(bits);
                wire.words[1] = static_cast<uint32_t>(bits >> 32);
            }
        });
        return;
    }
    if (parser.acceptWord("String"_s)) {
        wire.kind = 5;
        parser.parseRecord([&] {
            if (parser.acceptField("value"_s))
                wire.words[0] = parser.parseStringWord();
        });
        return;
    }
    if (parser.acceptWord("BigInt"_s)) {
        wire.kind = 6;
        parser.parseRecord([&] {
            if (parser.acceptField("digits"_s))
                wire.words[0] = parser.parseStringWord();
        });
        return;
    }
    if (parser.acceptWord("Array"_s)) {
        wire.kind = 7;
        parser.parseRecord([&] {
            if (parser.acceptField("contents"_s))
                wire.words[0] = parser.parseTypeWord();
            if (parser.acceptField("elements"_s)) {
                Vector<Wire::DataNode> elements;
                parser.parseList(TokenKind::LeftBracket, TokenKind::RightBracket, [&] {
                    Wire::DataNode element;
                    parseVariant(parser, element);
                    elements.append(element);
                });
                Wire::Span span = parser.builder().appendRecords<Wire::DataNode>(elements.span());
                wire.words[1] = span.start;
                wire.words[2] = span.count;
            }
        });
        return;
    }
    if (parser.acceptWord("Object"_s)) {
        wire.kind = 8;
        parser.parseRecord([&] {
            if (parser.acceptField("layout"_s))
                wire.words[0] = parser.parseIDWord(IDPrefix::Layout);
            if (parser.acceptField("members"_s)) {
                Vector<Wire::DataMember> elements;
                parser.parseList(TokenKind::LeftBracket, TokenKind::RightBracket, [&] {
                    Wire::DataMember element;
                    parser.parseRecord([&] { parseFields(parser, element); });
                    elements.append(element);
                });
                Wire::Span span = parser.builder().appendRecords<Wire::DataMember>(elements.span());
                wire.words[1] = span.start;
                wire.words[2] = span.count;
            }
        });
        return;
    }
    parser.fail();
}

